import { useCallback, useEffect, useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Button } from "@/components/ui/button"
import { useToast } from "@/components/ui/use-toast"
import { useContract } from "@/hooks/useContract"
import { Loader2, AlertCircle, RefreshCw } from "lucide-react"
import { CandidateList } from "@/components/Dashboard/CandidateList"
import { getPublicElectionData, type ElectionState, type PublicElectionData } from "@/services/api"

export default function ElectionStatus() {
  const { toast } = useToast()
  const { getElectionState, startElection, endElection, isAdmin, isInitialized, isLoading: contractLoading } = useContract()
  const [state, setState] = useState<ElectionState | null>(null)
  const [publicData, setPublicData] = useState<PublicElectionData | null>(null)
  const [loading, setLoading] = useState(true)
  const [actionLoading, setActionLoading] = useState(false)
  const [error, setError] = useState<string | null>(null)

  const refresh = useCallback(async () => {
    if (!isInitialized) return
    setLoading(true)
    setError(null)
    try {
      const [contractState, electionData] = await Promise.all([getElectionState(), getPublicElectionData()])
      setState(contractState)
      setPublicData(electionData)
    } catch (refreshError) {
      setError(refreshError instanceof Error ? refreshError.message : "Failed to fetch election status")
    } finally {
      setLoading(false)
    }
  }, [isInitialized, getElectionState])

  useEffect(() => {
    void refresh()
  }, [refresh])

  const runLifecycleAction = async (action: "start" | "end") => {
    setActionLoading(true)
    try {
      if (action === "start") await startElection()
      else await endElection()
      toast({ title: "Success", description: action === "start" ? "Election is now Active." : "Election has ended." })
      await refresh()
    } catch (actionError) {
      toast({ title: "Transaction failed", description: actionError instanceof Error ? actionError.message : "Lifecycle transaction failed", variant: "destructive" })
    } finally {
      setActionLoading(false)
    }
  }

  if (!isInitialized || loading || contractLoading) {
    return <div className="max-w-3xl mx-auto py-8"><Card><CardHeader><CardTitle>Election Status</CardTitle></CardHeader><CardContent className="flex items-center justify-center py-12"><Loader2 className="h-8 w-8 animate-spin" /></CardContent></Card></div>
  }

  if (error || !state || !publicData) {
    return <div className="max-w-3xl mx-auto py-8"><Card><CardHeader><CardTitle>Election Status</CardTitle></CardHeader><CardContent className="text-center py-12"><AlertCircle className="h-8 w-8 mx-auto text-destructive" /><p className="text-destructive mt-3">{error || "Election status unavailable"}</p><Button onClick={refresh} variant="outline" className="mt-4"><RefreshCw className="mr-2 h-4 w-4" />Try Again</Button></CardContent></Card></div>
  }

  return (
    <div className="max-w-3xl mx-auto py-8 space-y-6">
      <Card>
        <CardHeader><CardTitle>Election Lifecycle</CardTitle></CardHeader>
        <CardContent className="space-y-4">
          <div className="flex items-center gap-2"><span className="font-medium">Current state:</span><Badge variant={state === "Active" ? "default" : "secondary"}>{state}</Badge></div>
          {isAdmin && state === "Registration" && <Button className="w-full" onClick={() => runLifecycleAction("start")} disabled={actionLoading}>{actionLoading ? "Starting..." : "Start Election"}</Button>}
          {isAdmin && state === "Active" && <Button className="w-full" variant="destructive" onClick={() => runLifecycleAction("end")} disabled={actionLoading}>{actionLoading ? "Ending..." : "End Election"}</Button>}
          {state === "Ended" && <p className="text-sm text-muted-foreground">The election is final. Registration, start, end, and voting actions are disabled.</p>}
        </CardContent>
      </Card>
      <CandidateList candidates={publicData.candidates} isLoading={false} />
    </div>
  )
}
