import { useCallback, useEffect, useState } from "react"
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card"
import { Badge } from "@/components/ui/badge"
import { Loader2, AlertCircle, RefreshCw } from "lucide-react"
import { Button } from "@/components/ui/button"
import { getPublicElectionData, type PublicElectionData } from "@/services/api"
import { CandidateList } from "@/components/Dashboard/CandidateList"

export function PublicDashboard() {
  const [data, setData] = useState<PublicElectionData | null>(null)
  const [loading, setLoading] = useState(true)
  const [error, setError] = useState<string | null>(null)

  const fetchPublicElectionData = useCallback(async () => {
    setLoading(true)
    setError(null)
    try {
      setData(await getPublicElectionData())
    } catch (requestError) {
      console.error("Failed to load public election data", requestError)
      setError(requestError instanceof Error ? requestError.message : "Could not fetch election data")
    } finally {
      setLoading(false)
    }
  }, [])

  useEffect(() => {
    void fetchPublicElectionData()
  }, [fetchPublicElectionData])

  if (loading) {
    return (
      <div className="container mx-auto p-6">
        <Card>
          <CardHeader><CardTitle>Public Dashboard</CardTitle></CardHeader>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <Loader2 className="h-8 w-8 animate-spin text-muted-foreground" />
            <p className="text-muted-foreground mt-4">Loading election data...</p>
          </CardContent>
        </Card>
      </div>
    )
  }

  if (error || !data) {
    return (
      <div className="container mx-auto p-6">
        <Card>
          <CardHeader><CardTitle>Public Dashboard</CardTitle></CardHeader>
          <CardContent className="flex flex-col items-center justify-center py-12">
            <AlertCircle className="h-8 w-8 text-destructive" />
            <p className="text-destructive mt-4">{error || "Election data unavailable"}</p>
            <Button variant="outline" onClick={fetchPublicElectionData} className="mt-4">
              <RefreshCw className="h-4 w-4 mr-2" /> Try Again
            </Button>
          </CardContent>
        </Card>
      </div>
    )
  }

  const totalVotes = data.candidates.reduce((sum, candidate) => sum + candidate.voteCount, 0)

  return (
    <div className="container mx-auto p-6 space-y-6">
      <Card>
        <CardHeader><CardTitle>Public Dashboard</CardTitle></CardHeader>
        <CardContent>
          <div className="flex items-center gap-2">
            <span className="text-lg font-semibold">Election State</span>
            <Badge variant={data.electionState === "Active" ? "default" : "secondary"}>
              {data.electionState}
            </Badge>
          </div>
          <div className="mt-2 text-sm">
            <span className="font-medium">On-chain candidates with metadata:</span> {data.candidateCount}<br />
            <span className="font-medium">Authoritative total votes:</span> {totalVotes}
          </div>
        </CardContent>
      </Card>

      <CandidateList candidates={data.candidates} isLoading={false} />
    </div>
  )
}
